INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('334d5612-7e2c-4ed6-ae33-b9530ae1d87d', (SELECT id FROM public.quizzes WHERE slug = 'net-ip-routing-check'), 'Which statements about private IP addresses are correct? (Select all correct answers)', 'multiple_select', NULL, 'Private IPv4 addresses are used inside local networks, can be reused across organizations, and rely on NAT for external Internet traffic.', 7);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('4b818d4b-7516-4471-ac84-45f4f1a16638', '334d5612-7e2c-4ed6-ae33-b9530ae1d87d', 'A', 'They are commonly used inside home and office networks.', 1);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('39e8a117-a1bd-4a47-ad50-4fce6e22912d', '334d5612-7e2c-4ed6-ae33-b9530ae1d87d', 'B', 'They can be reused in different private networks.', 2);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('f49b5242-0ba8-4cb7-aa3a-072324e72440', '334d5612-7e2c-4ed6-ae33-b9530ae1d87d', 'C', 'They are always directly reachable from the public Internet.', 3);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('f5af32fc-1c0c-4853-ad1d-63aa4845b8e9', '334d5612-7e2c-4ed6-ae33-b9530ae1d87d', 'D', 'A router commonly uses NAT to provide external connectivity to private-network devices.', 4);
INSERT INTO public.quiz_answer_keys (question_id, correct_option_ids, accepted_answers) VALUES ('334d5612-7e2c-4ed6-ae33-b9530ae1d87d', ARRAY['4b818d4b-7516-4471-ac84-45f4f1a16638'::UUID, '39e8a117-a1bd-4a47-ad50-4fce6e22912d'::UUID, 'f5af32fc-1c0c-4853-ad1d-63aa4845b8e9'::UUID]::UUID[], ARRAY[]::TEXT[]);
INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('89d162e6-4d47-421b-a480-5f07aef342b0', (SELECT id FROM public.quizzes WHERE slug = 'net-ip-routing-check'), 'You have the network 192.168.1.0/24 and borrow 2 host bits to create equal-sized subnets. Which statements are correct? (Select all correct answers)', 'multiple_select', NULL, 'Borrowing 2 bits from /24 yields 2^2 = 4 subnets with a /26 prefix, each containing 64 total addresses and 62 usable host addresses.', 8);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('18a7d02b-17f0-42d6-aed8-8b78a875b040', '89d162e6-4d47-421b-a480-5f07aef342b0', 'A', 'Four subnets are created.', 1);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('bbcb9aee-c725-4515-ab64-b66014108e88', '89d162e6-4d47-421b-a480-5f07aef342b0', 'B', 'The new prefix is /26.', 2);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('9b813857-2ff0-4baa-a094-3e3b3ecf4c5d', '89d162e6-4d47-421b-a480-5f07aef342b0', 'C', 'Each subnet has 128 total addresses.', 3);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('cd2a12d5-d221-46b3-a95e-7ca0a19cdd36', '89d162e6-4d47-421b-a480-5f07aef342b0', 'D', 'Each subnet normally has 62 usable host addresses.', 4);
INSERT INTO public.quiz_answer_keys (question_id, correct_option_ids, accepted_answers) VALUES ('89d162e6-4d47-421b-a480-5f07aef342b0', ARRAY['18a7d02b-17f0-42d6-aed8-8b78a875b040'::UUID, 'bbcb9aee-c725-4515-ab64-b66014108e88'::UUID, 'cd2a12d5-d221-46b3-a95e-7ca0a19cdd36'::UUID]::UUID[], ARRAY[]::TEXT[]);
INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('4f1c2813-d783-4063-aa1c-7b4f2feddc91', (SELECT id FROM public.quizzes WHERE slug = 'net-ip-routing-check'), 'A computer can have multiple IP addresses if it has multiple network interfaces or address configurations.', 'true_false', NULL, 'True — a device can have multiple interfaces (loopback, Ethernet, Wi-Fi, VPN) and multiple IP addresses.', 9);
INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('a9462f5c-2d46-4d82-aac9-83a083d9310c', '4f1c2813-d783-4063-aa1c-7b4f2feddc91', 'A', 'True', 1);
