INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('ed9f0151-cb2a-4ed2-a62d-436e9646d6a8', '825273e2-7d9b-4108-a97a-73d65f4fdb8e', 'A', 'True', 1);
