INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('e603e9ce-c7a3-48a8-a541-6b11830cb22e', (SELECT id FROM public.quizzes WHERE slug = 'net-mac-arp-switching-check'), 'Which statements about VLANs are correct? (Select all correct answers)', 'multiple_select', NULL, 'VLANs logically segment a physical switch into separate Layer 2 broadcast domains and require Layer 3 routing for inter-VLAN traffic.', 8);
