INSERT INTO public.quizzes (id, slug, title, description, category, difficulty, lesson_id, pass_percentage, status) VALUES ('0d47f5ff-445f-494a-a7e4-36f7245f7717', 'web-http-anatomy-check', 'Module 01 Knowledge Check — HTTP Anatomy & Trust Boundaries', 'Verify your grasp of HTTP headers, secure session cookie flags (HttpOnly, Secure, SameSite), and server-side validation.', 'web-security', 'intermediate', 'web-001', 100, 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, pass_percentage = EXCLUDED.pass_percentage, status = EXCLUDED.status, updated_at = NOW();
