INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('6aea7e9c-94c3-4a0d-aa97-c6b2d6d97cd2', (SELECT id FROM public.quizzes WHERE slug = 'web-http-anatomy-check'), 'Why must authorization and input validation always be enforced on the server even when checked in browser forms?', 'single_choice', NULL, 'Browsers run on untrusted client machines where hidden fields, localStorage, and headers can all be forged directly.', 3);
