INSERT INTO public.quiz_options (id, question_id, label, option_text, sort_order) VALUES ('4ac395c0-6508-460d-a3a2-98eda69eb586', 'dd758a2f-190b-490f-abb6-6613145ed010', 'A', 'X-Content-Type-Options: nosniff', 1);
