INSERT INTO public.quiz_questions (id, quiz_id, prompt, question_type, placeholder, explanation, sort_order) VALUES ('2ec4ecaf-edb2-4a08-a96b-41e443ad4faa', (SELECT id FROM public.quizzes WHERE slug = 'web-security-headers-check'), 'https://app.example.com:443 and http://app.example.com:80 are considered the same origin by browsers.', 'true_false', NULL, 'False — both the scheme (https vs http) and port (443 vs 80) differ, so browsers treat them as cross-origin.', 4);
