INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('de9c448e-05a3-43d4-a384-ff4617f5d48b', 'explore-linux-environment', 'Verify Your Local Linux Shell Environment', 'Identify your kernel version, current user, shell path, and manual page documentation from your terminal.', 'linux', 'beginner', 'linux-001', ARRAY['Local Linux terminal, WSL2, or authorized Ubuntu VM']::TEXT[], ARRAY['Open your local terminal and run whoami, uname -a, and echo $SHELL.', 'Run man ls to view the manual page for ls, search with /size, and press q to exit.', 'Record the distribution and kernel release shown on your system.']::TEXT[], 'You can verify system identity and navigate man pages confidently without external search.', 'Execute these commands only on your own computer or an authorized lab environment.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('36b97926-8b68-441a-a3fc-067bd9747b9b', 'explore-linux-filesystem', 'Explore the Linux Filesystem Hierarchy', 'Inspect core system directories (/etc, /var, /home, /tmp) and practice switching between absolute and relative paths.', 'linux', 'beginner', 'linux-002', ARRAY['Completed Module 02']::TEXT[], ARRAY['Run pwd and ls -la / to map top-level directories.', 'Navigate into /etc using an absolute path and inspect read-only metadata with ls -l.', 'Return to your home directory using cd ~.']::TEXT[], 'Clear understanding of where configuration files, logs, and user home directories reside.', 'Do not modify or delete any files inside system directories such as /etc or /var.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('1d3618cb-9249-42c5-ae65-594488efe054', 'manage-local-workspace-files', 'Build and Organize a Practice Workspace', 'Create nested directories, copy configuration templates, rename files, and safely clean up temporary artifacts.', 'linux', 'beginner', 'linux-003', ARRAY['Completed Module 03']::TEXT[], ARRAY['Create ~/forgesec-workspace/notes and ~/forgesec-workspace/backups using mkdir -p.', 'Create sample.txt with touch, copy it to backups/sample.bak, and rename the original using mv.', 'Verify structure with ls -R ~/forgesec-workspace.']::TEXT[], 'Full command-line fluency creating, copying, moving, and inspecting local workspace directories.', 'Double-check target paths before running rm -r; practice strictly inside ~/forgesec-workspace.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('1682de74-f253-4ab4-a178-ac79c5b86c4f', 'analyze-sample-auth-logs', 'Analyze Sample Authentication Logs', 'Filter failed authentication events and summarize repeated patterns using grep, sort, uniq, and wc.', 'linux', 'beginner', 'linux-004', ARRAY['Completed Module 04']::TEXT[], ARRAY['Create a local sample-auth.log file with both Accepted and Failed login lines.', 'Isolate failed lines using grep -n "Failed" sample-auth.log.', 'Count unique matching entries via sort | uniq -c | wc -l.']::TEXT[], 'Ability to slice and count log indicators cleanly from the shell.', 'Practice exclusively on synthetic or self-owned local log files.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('beff3563-0e8f-49e7-a481-dd6eccdfdc98', 'audit-local-file-permissions', 'Audit and Harden Local File Permissions', 'Apply least-privilege chmod octal permissions (600, 700, 640) inside a local scratch folder.', 'linux', 'beginner', 'linux-005', ARRAY['Completed Module 05']::TEXT[], ARRAY['Create secret-key.txt and helper.sh inside ~/forgesec-workspace.', 'Run chmod 600 secret-key.txt and chmod 700 helper.sh.', 'Verify exact mode bits with ls -l.']::TEXT[], 'ls -l confirms -rw------- and -rwx------ with zero group/world access.', 'Never run recursive chmod across system directories.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('e27ee153-95aa-4c84-ad2c-dc4b16b1a970', 'inspect-installed-packages', 'Inspect Package Repositories and Installed Tools', 'Query installed packages, inspect metadata with apt show, and audit recent package history.', 'linux', 'beginner', 'linux-006', ARRAY['Debian/Ubuntu environment with APT']::TEXT[], ARRAY['Run apt list --installed | head -n 20 to review installed packages.', 'Inspect details for openssh-client using apt show openssh-client.', 'Review configured sources read-only in /etc/apt/sources.list.']::TEXT[], 'Clear visibility into package origins and versions.', 'Only inspect repositories or install signed packages from official distribution mirrors.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('02269f43-8831-439b-a382-1e01638d4fb3', 'inspect-running-processes', 'Inspect Active Processes and Resource Usage', 'List running processes, filter by user or command name, and observe parent/child PID relationships.', 'linux', 'beginner', 'linux-007', ARRAY['Completed Module 07']::TEXT[], ARRAY['Run ps aux | head -n 20 and identify PID, USER, %CPU, and COMMAND columns.', 'Start sleep 120 & in the background, inspect it with jobs and ps, then terminate it gracefully with kill.', 'Confirm the background process is gone.']::TEXT[], 'Practical familiarity inspecting processes and terminating test jobs safely.', 'Only send signals to test processes owned by your user account.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('03b002e1-d33c-4164-ac6f-114861dd21bc', 'audit-local-systemd-services', 'Audit Local Systemd Services', 'Enumerate active systemd service units and verify which background daemons start on boot.', 'linux', 'beginner', 'linux-008', ARRAY['Systemd-based Linux distribution']::TEXT[], ARRAY['Run systemctl list-units --type=service --state=running.', 'Check status for a core local service such as systemd-journald.', 'Review recent unit logs using journalctl -n 20 --no-pager.']::TEXT[], 'Ability to verify running services and read unit logs cleanly.', 'Do not stop critical system services on a shared or production machine.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('c29a661a-6585-4a61-a1cc-068e77de8621', 'inspect-local-network-interfaces', 'Inspect Local Interfaces and Listening Sockets', 'Inspect host IPv4/IPv6 addresses, routing table, and active listening TCP/UDP sockets.', 'networking', 'beginner', 'linux-009', ARRAY['Completed Module 09 or Networking Module 01']::TEXT[], ARRAY['Run ip addr show and ip route show.', 'Run ss -tulnp to list active listening sockets.', 'Identify services bound to 127.0.0.1 vs 0.0.0.0.']::TEXT[], 'Accurate inventory of your machine''s network exposure.', 'Restrict socket and network inspection strictly to hosts you own or have permission to audit.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('2ecf5063-5e29-42f2-a5bd-23b68be6617d', 'configure-and-inspect-ssh-client', 'Generate Ed25519 Keys and Inspect SSH Client Config', 'Create a dedicated local SSH key pair with strict 700/600 permissions and configure a clean host alias.', 'networking', 'beginner', 'linux-010', ARRAY['OpenSSH client installed']::TEXT[], ARRAY['Generate a test Ed25519 key pair in a practice folder using ssh-keygen -t ed25519.', 'Ensure directory permissions are 700 and private key permissions are 600.', 'Review ~/.ssh/config structure for specifying Host, HostName, User, and IdentityFile.']::TEXT[], 'Properly permissioned SSH key pair and structured client configuration.', 'Never expose SSH publicly without key-based authentication and explicit firewall controls.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('3e6e4741-b103-4505-ac7e-1ef7b051d2a4', 'explore-local-network-basics', 'Explore Your Local Network Interfaces and Gateway', 'Use ip link, ip addr, and ip route to identify your active network interfaces, MAC address, IPv4 address, and default gateway.', 'networking', 'beginner', 'net-001', ARRAY['Linux terminal, WSL2, or authorized Ubuntu VM']::TEXT[], ARRAY['Run ip link to list your network interfaces and identify which interface is UP.', 'Run ip addr to record your active IPv4 address and MAC (link/ether) address.', 'Run ip route to identify your default gateway and outgoing interface.']::TEXT[], 'You can identify your active interface, local IPv4 address, MAC address, and default gateway from the Linux terminal.', 'Only inspect network interfaces on machines and networks you own or are authorized to use.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('5815d3e9-b00f-4e2f-a7e9-bab197c00008', 'explore-network-layers-linux', 'Explore Network Layers Using Linux Commands', 'Map real Linux diagnostic outputs (ip link, ip addr, ip route, ping) to the Physical, Data Link, Network, and Transport/Application layers.', 'networking', 'beginner', 'net-002', ARRAY['Completed Networking Module 02']::TEXT[], ARRAY['Run ip link to inspect Layer 1/2 interface state and MAC addresses.', 'Run ip addr and ip route to inspect Layer 3 IP addressing and routing tables.', 'Run ping -c 4 127.0.0.1 and ping -c 4 to your default gateway, then map each observation to its OSI and TCP/IP layer.']::TEXT[], 'Completed layer mapping connecting Linux CLI outputs to the OSI and TCP/IP models.', 'Perform these commands only on your own computer or an authorized lab VM.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('360658a6-64c9-4a3b-a7d0-c6654cd6df0a', 'understand-your-ip-network', 'Understand Your IP Network and Subnet Calculations', 'Inspect your host IPv4/IPv6 configuration, classify private vs. public addresses, and calculate subnet ranges for /24 and /26 prefixes.', 'networking', 'beginner', 'net-003', ARRAY['Completed Networking Module 03']::TEXT[], ARRAY['Run ip addr and ip route to record your primary IPv4 address, CIDR prefix length, and default gateway.', 'Determine whether your local IPv4 address belongs to an RFC 1918 private range.', 'Calculate the network address, broadcast address, and usable host count for 192.168.10.0/24 and 192.168.1.0/26.']::TEXT[], 'Accurate IP configuration report and verified subnetting calculations.', 'Only inspect network settings on devices you own or are permitted to administer.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('d4e71836-6d01-41af-a675-74b34cb44ac0', 'investigate-local-network-arp', 'Investigate Your Local Network, MAC Table and ARP Cache', 'Inspect local interface MAC addresses, generate traffic to your default gateway, and examine the Linux neighbor (ARP) cache.', 'networking', 'beginner', 'net-004', ARRAY['Completed Networking Module 04']::TEXT[], ARRAY['Run ip link to record your active interface''s 48-bit MAC address.', 'Run ip route to identify your default gateway IP, then ping the gateway with ping -c 2 <gateway-ip>.', 'Run ip neigh to inspect the ARP/neighbor cache and record the MAC address and reachability state of your gateway.']::TEXT[], 'Clear explanation of how IP, ARP, and MAC addresses work together for local and off-subnet delivery.', 'Do not perform unauthorized network scanning; restrict testing to your own interface and default gateway.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('b8ffab51-cb4f-49a2-a304-837793dd5cbe', 'tcp-udp-and-port-investigation', 'TCP, UDP and Listening Port Investigation', 'Audit listening TCP/UDP sockets with ss, query the local service database, and trace an HTTPS connection.', 'networking', 'beginner', 'net-005', ARRAY['Completed Networking Module 05']::TEXT[], ARRAY['Run ss -tuln and sudo ss -tulpn to list listening TCP and UDP ports on your system.', 'Run getent services ssh, getent services http, and getent services https to verify standard port mappings.', 'Run curl -I https://example.com and explain the five-tuple and TCP three-way handshake used for the connection.']::TEXT[], 'Completed socket inventory and transport-layer analysis report.', 'Only inspect sockets on your own system; never scan external hosts without permission.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('022cf351-1469-4b27-a530-fb8a6d1defab', 'investigate-dns-dhcp-and-nat', 'Investigate DNS Resolution, DHCP Configuration and NAT', 'Inspect configured DNS resolvers, query A/AAAA/MX/TXT records with dig, and compare private LAN addressing against NAT.', 'networking', 'beginner', 'net-006', ARRAY['Completed Networking Module 06']::TEXT[], ARRAY['Inspect your DNS configuration with resolvectl status or cat /etc/resolv.conf.', 'Run dig example.com A, AAAA, MX, and TXT and record the returned answers and TTL values.', 'Run ip addr and ip route to identify your private IPv4 address and default gateway, and explain how NAT translates outbound traffic.']::TEXT[], 'Documented DNS record lookups and a clear explanation of DNS, DHCP (DORA), and NAT on your network.', 'Do not publicly post sensitive internal or public IP configuration details.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('93109606-542c-42a7-a7d2-fae7d4e2e010', 'linux-network-diagnostic-report', 'Linux Network Diagnostic Report', 'Execute a complete 8-step Linux network troubleshooting workflow from link state and routing to DNS, sockets, and ICMP capture.', 'networking', 'beginner', 'net-007', ARRAY['Completed Networking Module 07']::TEXT[], ARRAY['Verify interface and routing state using ip link, ip addr, and ip route.', 'Test loopback, gateway, and external reachability with ping -c 4, then verify DNS resolution with getent hosts example.com and dig example.com.', 'Inspect listening sockets with ss -tuln, test HTTP headers with curl -I https://example.com, and write a structured diagnostic report.']::TEXT[], 'Complete evidence-based Linux network diagnostic report covering interfaces, routes, DNS, and sockets.', 'Run diagnostic commands only on systems and networks you own or have explicit permission to test.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
INSERT INTO public.assignments (id, slug, title, objective, category, difficulty, lesson_id, prerequisites, instructions, expected_outcome, safety_warning, status) VALUES ('776ee265-4b0a-428f-a24a-46aa7479d202', 'network-traffic-analysis-lab', 'Network Traffic Analysis Lab with tcpdump and Wireshark', 'Capture live ICMP, DNS, and HTTPS packets into a .pcap file using tcpdump and inspect protocol headers and TCP handshakes in Wireshark.', 'networking', 'beginner', 'net-008', ARRAY['Completed Networking Module 08', 'tcpdump and Wireshark installed']::TEXT[], ARRAY['List capture interfaces with sudo tcpdump -D and capture 100 packets with sudo tcpdump -ni any -c 100 -w lesson8.pcap while running ping, dig, and curl.', 'Inspect the saved capture in the terminal with tcpdump -nn -r lesson8.pcap.', 'Open lesson8.pcap in Wireshark, apply icmp, dns, tcp, and tcp.port == 443 display filters, and document the TCP three-way handshake and HTTPS encryption observations.']::TEXT[], 'Final packet-analysis diagnostic report identifying ICMP, DNS, TCP handshake stages, and TLS-encrypted HTTPS traffic.', 'Capture packets exclusively on your own machine or an isolated lab network you are authorized to inspect.', 'published') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, objective = EXCLUDED.objective, category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, lesson_id = EXCLUDED.lesson_id, prerequisites = EXCLUDED.prerequisites, instructions = EXCLUDED.instructions, expected_outcome = EXCLUDED.expected_outcome, safety_warning = EXCLUDED.safety_warning, status = EXCLUDED.status, updated_at = NOW();
